151	// em dashes, periods and underscores, separates words.
152	const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;
153	
154	function assertText(fn, value) {
155	  if (typeof value !== 'string') {
156	    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
157	  }
158	}
159	
160	// Private: the single definition of "word" shared by every statistic below.
161	function tokenize(text) {
162	  return text.match(WORD_PATTERN) ?? [];
163	}
164	
165	/**
166	 * Count the words in a piece of text.
167	 *
168	 * @param {string} text
169	 * @returns {number}
170	 */
171	function wordCount(text) {
172	  assertText('wordCount', text);
173	  return tokenize(text).length;
174	}
175	
176	module.exports = { wordCount };
