295	```javascript
296	// Words whose trailing period does not end a sentence. Compared lower-case and
297	// without any opening bracket or quote. "U.S.A." style initialisms are not
298	// listed: they usually do end a sentence when they come last, and guessing
299	// otherwise would trade one error for another.
300	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
301	
302	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
303	// only where whitespace or the end of the text follows. Requiring that keeps
304	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
305	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
306	
307	function endsWithAbbreviation(before) {
308	  const last = before.match(/(\S+)$/);
309	  if (last === null) {
310	    return false;
311	  }
312	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
313	  return ABBREVIATIONS.has(word);
314	}
315	
316	/**
317	 * Count the sentences in a piece of text.
318	 *
319	 * A sentence is a stretch of text containing at least one word and ending at a
320	 * terminator run, or at the end of the text. A lone period after a known
321	 * abbreviation does not end a sentence.
322	 *
323	 * @param {string} text
324	 * @returns {number}
325	 */
326	function sentenceCount(text) {
327	  assertText('sentenceCount', text);
328	  let count = 0;
329	  let start = 0;
330	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
331	    const before = text.slice(start, match.index);
332	    if (match[1] === '.' && endsWithAbbreviation(before)) {
333	      continue;
334	    }
335	    if (tokenize(before).length > 0) {
336	      count += 1;
337	    }
338	    start = match.index + match[0].length;
339	  }
340	  if (tokenize(text.slice(start)).length > 0) {
341	    count += 1;
342	  }
343	  return count;
344	}
345	
346	module.exports = { wordCount, sentenceCount };
347	```
